from shop.cart import Cart
from shop.pricing import compute_total
from shop.report import summary


class T(unittest.TestCase):
    def test_total(self): self.assertEqual(compute_total([(1.5, 2), (2.0, 1)]), 5.0)
    def test_total_with_tax(self): self.assertEqual(compute_total([(1.5, 2), (2.0, 1)], tax_rate=0.1), 5.5)
