        c = Cart(); c.add(10.0, 2); self.assertEqual(c.checkout(), 20.0)
    def test_cart_with_tax(self):
        c = Cart(tax_rate=0.1); c.add(10.0, 2); self.assertEqual(c.checkout(), 22.0)
    def test_report(self):
        c = Cart(); c.add(10.0, 2); self.assertEqual(summary(c), "1 lines, total 20.00")
    def test_report_with_tax(self):
        c = Cart(tax_rate=0.1); c.add(10.0, 2); self.assertEqual(summary(c), "1 lines, total 22.00")


if __name__ == "__main__":
    unittest.main()
